<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { buscarProveedoresCompra, cambiarEstadoRegistroCompra, guardarRegistroCompra, listarRegistroCompras } from '../services/registroCompras'
import type { CompraOption, FiltrosCompra, ProveedorCompra, RegistroCompra, RegistroCompraPayload } from '../interfaces/registroCompras.interface'
const blank=():RegistroCompraPayload=>({documento_id:0,serie:'',numerom:'',proveedor_id:null,fecha:new Date().toISOString().slice(0,10),tipoorden_id:null,numeroorden:null,moneda_id:0,compcontable:null,compdetraccion:null,fechadetraccion:null,fechavcto:null,impuesto:'IGV',estadoreg:'GR',inccreditofiscal:false,glosa:null,importegravado:0,importenogravado:0,importeimpuesto:0,importeir:0,importetotal:0})
const rows=ref<RegistroCompra[]>([]),documentos=ref<CompraOption[]>([]),monedas=ref<CompraOption[]>([]),tiposOrden=ref<CompraOption[]>([]),proveedores=ref<ProveedorCompra[]>([]),proveedorQuery=ref(''),proveedorTexto=ref(''),igv=ref(18),isc=ref(0),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null)
const filters=reactive<FiltrosCompra>({criterio:'',documento_id:'',moneda_id:'',estadoreg:'',fecha_desde:'',fecha_hasta:''}),form=reactive<RegistroCompraPayload>(blank())
const impuestoPct=computed(()=>form.impuesto==='IGV'?igv.value:form.impuesto==='ISC'?isc.value:0)
const message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la operación.'
function recalculate(){form.importeimpuesto=Number((Number(form.importegravado||0)*impuestoPct.value/100).toFixed(4));form.importetotal=Number((Number(form.importegravado||0)+Number(form.importenogravado||0)+form.importeimpuesto+Number(form.importeir||0)).toFixed(4))}
watch(()=>[form.importegravado,form.importenogravado,form.importeir,form.impuesto],recalculate)
async function load(next=1){loading.value=true;error.value='';try{const r=await listarRegistroCompras(filters,next);rows.value=r.data;documentos.value=r.options.documentos;monedas.value=r.options.monedas;tiposOrden.value=r.options.tipos_orden;igv.value=r.options.porcentaje_igv??18;isc.value=r.options.porcentaje_isc??0;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total}catch(v){error.value=message(v)}finally{loading.value=false}}
function clear(){Object.keys(filters).forEach(k=>filters[k as keyof FiltrosCompra]='');load(1)}
function open(item?:RegistroCompra){editing.value=item?.id??null;Object.assign(form,item?{documento_id:item.documento_id,serie:item.serie,numerom:item.numerom,proveedor_id:item.proveedor_id,fecha:item.fecha,tipoorden_id:item.tipoorden_id,numeroorden:item.numeroorden,moneda_id:item.moneda_id,compcontable:item.compcontable,compdetraccion:item.compdetraccion,fechadetraccion:item.fechadetraccion,fechavcto:item.fechavcto,impuesto:item.impuesto,estadoreg:item.estadoreg,inccreditofiscal:item.inccreditofiscal,glosa:item.glosa,importegravado:Number(item.importegravado),importenogravado:Number(item.importenogravado),importeimpuesto:Number(item.importeimpuesto),importeir:Number(item.importeir),importetotal:Number(item.importetotal)}:blank());proveedorTexto.value=item?.proveedor??'';proveedorQuery.value='';proveedores.value=[];error.value='';modal.value=true}
async function searchProvider(){if(proveedorQuery.value.trim().length<3)return void(error.value='Ingrese al menos 3 caracteres para buscar proveedor.');try{proveedores.value=await buscarProveedoresCompra(proveedorQuery.value.trim())}catch(v){error.value=message(v)}}
function chooseProvider(p:ProveedorCompra){form.proveedor_id=p.id;proveedorTexto.value=p.texto;proveedores.value=[];proveedorQuery.value=''}
async function save(){if(!form.documento_id||!form.moneda_id||!form.serie.trim()||!form.numerom.trim()||!form.fecha)return void(error.value='Complete documento, serie, número, fecha y moneda.');if(form.importetotal<0)return void(error.value='El importe total no puede ser negativo.');saving.value=true;try{await guardarRegistroCompra(editing.value,{...form,serie:form.serie.toUpperCase(),numerom:form.numerom.trim()});modal.value=false;success.value=`Registro ${editing.value?'actualizado':'creado'} correctamente.`;await load(editing.value?page.value:1)}catch(v){error.value=message(v)}finally{saving.value=false}}
async function toggle(item:RegistroCompra){if(!confirm(`¿Desea ${item.estado?'desactivar':'activar'} ${item.serie}-${item.numerom}?`))return;try{await cambiarEstadoRegistroCompra(item.id);success.value='Estado actualizado correctamente.';await load(page.value)}catch(v){error.value=message(v)}}
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/administracion/contabilidad">Contabilidad</RouterLink> / Registro de compras</nav><header class="hero"><div class="mark">RC</div><div><small>MIA · CONTABILIDAD · MOVIMIENTOS</small><h1>Registro de compras</h1><p>Administra comprobantes de proveedores, impuestos, detracciones y crédito fiscal.</p></div><strong>{{total}} registros</strong><button @click="open()">+ Nuevo registro</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><form class="filters" @submit.prevent="load(1)"><input v-model.trim="filters.criterio" placeholder="Serie, número o glosa"><select v-model="filters.documento_id"><option value="">Todos los documentos</option><option v-for="o in documentos" :key="o.id" :value="o.id">{{o.codigo}} - {{o.nombre}}</option></select><select v-model="filters.moneda_id"><option value="">Todas las monedas</option><option v-for="o in monedas" :key="o.id" :value="o.id">{{o.nombre}}</option></select><select v-model="filters.estadoreg"><option value="">Todos</option><option value="GR">Gravada</option><option value="NG">No gravada</option></select><input v-model="filters.fecha_desde" type="date"><input v-model="filters.fecha_hasta" type="date"><button>Filtrar</button><button type="button" class="soft" @click="clear">Limpiar</button></form><section class="table-card"><div v-if="loading" class="empty">Consultando compras…</div><div v-else-if="!rows.length" class="empty">No se encontraron registros de compra.</div><div v-else class="scroll"><table><thead><tr><th>Documento</th><th>Serie-Número</th><th>Proveedor</th><th>Fecha</th><th>Moneda</th><th>Registro</th><th>Total</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td>{{item.documento?.codigo||'—'}}</td><td><b>{{item.serie}}-{{item.numerom}}</b></td><td>{{item.proveedor||'—'}}</td><td>{{item.fecha}}</td><td>{{item.moneda?.abreviatura||item.moneda?.nombre||'—'}}</td><td>{{item.estadoreg==='GR'?'Gravada':'No gravada'}}</td><td class="number">{{Number(item.importetotal).toFixed(4)}}</td><td><span :class="item.estado?'ok':'bad'">{{item.estado?'Activo':'Inactivo'}}</span></td><td class="actions"><button class="edit" @click="open(item)">Editar</button><button class="soft" @click="toggle(item)">Estado</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div><small>REGISTRO DE COMPRA</small><h2>{{editing?'Editar':'Nuevo'}} comprobante</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Documento *<select v-model.number="form.documento_id"><option :value="0">Seleccione</option><option v-for="o in documentos" :key="o.id" :value="o.id">{{o.codigo}} - {{o.nombre}}</option></select></label><label>Serie *<input v-model="form.serie" maxlength="5"></label><label>Número *<input v-model="form.numerom" maxlength="10"></label><label>Fecha *<input v-model="form.fecha" type="date"></label><label>Moneda *<select v-model.number="form.moneda_id"><option :value="0">Seleccione</option><option v-for="o in monedas" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label><label>Estado registro *<select v-model="form.estadoreg"><option value="GR">Gravada</option><option value="NG">No gravada</option></select></label><label>Tipo de orden<select v-model="form.tipoorden_id"><option :value="null">Sin orden</option><option v-for="o in tiposOrden" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label><label>Número de orden<input v-model="form.numeroorden" maxlength="20"></label><label class="span2">Proveedor<div class="provider"><input v-model="proveedorQuery" placeholder="RUC o razón social"><button type="button" @click="searchProvider">Buscar</button></div><span v-if="proveedorTexto" class="chosen">✓ {{proveedorTexto}}</span></label><div v-if="proveedores.length" class="results span2"><button v-for="p in proveedores" :key="p.id" type="button" @click="chooseProvider(p)">{{p.texto}}</button></div><label>Comprobante contable<input v-model="form.compcontable" maxlength="20"></label><label>Comprobante detracción<input v-model="form.compdetraccion" maxlength="20"></label><label>Fecha detracción<input v-model="form.fechadetraccion" type="date"></label><label>Fecha vencimiento<input v-model="form.fechavcto" type="date"></label><label>Impuesto<select v-model="form.impuesto"><option :value="null">Sin impuesto</option><option value="IGV">IGV ({{igv}}%)</option><option value="ISC">ISC ({{isc}}%)</option></select></label><label class="check"><input v-model="form.inccreditofiscal" type="checkbox"> Incluye crédito fiscal</label><label class="span2">Glosa<textarea v-model="form.glosa" maxlength="500"></textarea></label></div><h3>Importes</h3><div class="amounts"><label>Gravado<input v-model.number="form.importegravado" type="number" step="0.0001"></label><label>No gravado<input v-model.number="form.importenogravado" type="number" step="0.0001"></label><label>Impuesto<input :value="form.importeimpuesto.toFixed(4)" readonly></label><label>IR<input v-model.number="form.importeir" type="number" step="0.0001"></label><label class="total">Total<input :value="form.importetotal.toFixed(4)" readonly></label></div><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">Guardar registro</button></footer></form></div></div></template>
<style scoped>
.page{--a:#385d8a;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--a);text-decoration:none}.hero{padding:20px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--a);border-radius:12px;background:#fff}.mark{width:48px;height:48px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--a);font-weight:800}.hero small,.dialog small{color:var(--a);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.hero strong{margin-left:auto;font-size:.55rem}.hero button,.filters button,.table-card footer button,.dialog button{padding:9px 12px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.52rem}.flash{padding:9px;border-radius:7px;font-size:.6rem}.success{color:#287052;background:#edf9f3}.error{color:#a64046;background:#fff0f0}.filters{margin-top:10px;padding:13px;display:grid;grid-template-columns:repeat(4,1fr);gap:7px;background:#fff}.filters input,.filters select,.dialog input,.dialog select,.dialog textarea{width:100%;box-sizing:border-box;padding:8px;border:1px solid #d7dfe2;border-radius:6px;font:inherit;font-size:.53rem;background:#fff}.soft{color:#64727a!important;background:#edf1f3!important}.table-card{margin-top:10px;background:#fff;overflow:hidden}.scroll{overflow:auto}table{width:100%;min-width:900px;border-collapse:collapse;font-size:.5rem}th,td{padding:9px;border-bottom:1px solid #e8ecee;text-align:left}th{color:#fff;background:#4c627e}.number{text-align:right}.ok,.bad{padding:4px 7px;border-radius:10px;font-size:.43rem}.ok{color:#287154;background:#e6f7ee}.bad{color:#9d4046;background:#fdebed}.actions{display:flex;gap:4px}.actions button{padding:6px;border:0;border-radius:5px;font-size:.44rem}.edit{color:#385d8a;background:#e8eff8}.empty{padding:45px;text-align:center}.table-card>footer{padding:10px;display:flex;justify-content:center;gap:9px}.backdrop{position:fixed;z-index:100;inset:0;padding:14px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(900px,100%);max-height:94vh;overflow:auto;padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex;justify-content:space-between}.dialog h2{margin:3px 0 14px;font-size:.9rem}.dialog>header button{color:#59666c;background:none;font-size:1.1rem}.grid,.amounts{display:grid;grid-template-columns:repeat(4,1fr);gap:9px}.dialog label{display:grid;gap:4px;font-size:.48rem}.span2{grid-column:span 2}.provider{display:flex;gap:4px}.chosen{color:#287154}.results{display:grid;max-height:120px;overflow:auto}.results button{text-align:left;color:#35464e;background:#f1f5f7}.check{display:flex!important;align-items:center}.check input{width:auto}.amounts{grid-template-columns:repeat(5,1fr)}.total{font-weight:800}.dialog>footer{margin-top:14px;display:flex;justify-content:flex-end;gap:6px}@media(max-width:800px){.hero{flex-wrap:wrap}.hero strong{margin-left:0}.filters,.grid,.amounts{grid-template-columns:1fr 1fr}}@media(max-width:520px){.filters,.grid,.amounts{grid-template-columns:1fr}.span2{grid-column:auto}}
</style>
